class FundoJusticaResolver(QWidget):
    """Imagem com cover proporcional, escurecimento e mouse transparente."""
    def __init__(self, parent):
        super().__init__(parent)
        self.setObjectName("questionSolverJusticeBackdrop")
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setFocusPolicy(Qt.NoFocus)
        self._imagem = QPixmap()
        self._imagem_pb = QPixmap()
        self._b14_monocromatico = False
        try:
            self._imagem.loadFromData(base64.b85decode(_IMAGEM_B85), 'JPEG')
        except (ValueError, TypeError):
            pass
        self.setGeometry(parent.rect())
        self.show()
        self.lower()

    def alternar_monocromatico(self, ativo):
        self._b14_monocromatico = bool(ativo)
        if self._b14_monocromatico and self._imagem_pb.isNull() and not self._imagem.isNull():
            # Conversão única por sessão: não afeta a taxa de quadros.
            imagem_cinza = self._imagem.toImage().convertToFormat(QImage.Format_Grayscale8)
            self._imagem_pb = QPixmap.fromImage(imagem_cinza)
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.fillRect(self.rect(), QColor('#061322'))
        imagem = self._imagem_pb if self._b14_monocromatico and not self._imagem_pb.isNull() else self._imagem
        if not imagem.isNull() and self.width() and self.height():
            pw, ph = imagem.width(), imagem.height()
            aspect = self.width() / self.height()
            if pw/ph > aspect:
                sw, sh = ph*aspect, ph
            else:
                sw, sh = pw, pw/aspect
            src = QRectF((pw-sw)/2, (ph-sh)/2, sw, sh)
            painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
            # B08: o fundo continua estático e a imagem incorporada é idêntica
            # à do B07. O ET ganha um pequeno ajuste de enquadramento no topo,
            # mantendo a cabeça na região livre entre o progresso e o enunciado.
            # A compensação desaparece nas janelas compactas.
            deslocamento = 0
            if self.width() >= 1100 and self.height() >= 630:
                deslocamento = min(60, round(self.height() * 0.080))
            destino = QRectF(0, deslocamento, self.width(),
                             self.height() - deslocamento)
            painter.drawPixmap(destino, imagem, src)
        # Gradiente de proteção já existente no B07: mesmos pontos e cores.
        grad = QLinearGradient(0, 0, 0, max(1, self.height()))
        grad.setColorAt(0.0, QColor(2, 9, 18, 46))
        grad.setColorAt(0.60, QColor(2, 11, 21, 62))
        grad.setColorAt(1.0, QColor(1, 9, 19, 96))
        painter.fillRect(self.rect(), grad)

        # B13: removida a sombra localizada B08. O título da disciplina
        # migrou para o painel opaco do enunciado no B11; aquela sombra
        # sobrava no cenário e causava uma mancha escura à esquerda.
        largura = max(1, self.width())
        altura = max(1, self.height())

        # B08: piso discretamente mais escuro, sem perder os anéis e o V.
        # O início translúcido evita uma linha de corte visível.
        brilho_piso = QLinearGradient(0, altura * 0.73, 0, altura)
        brilho_piso.setColorAt(0.0, QColor(4, 9, 17, 0))
        brilho_piso.setColorAt(0.62, QColor(4, 9, 17, 18))
        brilho_piso.setColorAt(1.0, QColor(4, 9, 17, 49))
        painter.fillRect(QRectF(0, altura * 0.73,
                                largura, altura * 0.27), brilho_piso)
        painter.end()


def aplicar_fundo_justica(dialogo):
    """Retorna camada decorativa pronta; sem ações nem arquivos externos."""
    fundo = FundoJusticaResolver(dialogo)
    return fundo
